<?php $categories=$categories??[];$headExtra='<link rel="stylesheet" href="'.asset('css/catalog.css').'">';ob_start(); ?><section class="catalog-hero"><div class="site-container"><p class="eyebrow">ENCUENTRA TU ESTILO</p><p class="breadcrumbs"><a href="<?= url() ?>">Inicio</a><span>/</span>Categorías</p><h1>Categorías de fragancias</h1><p>Explora diferentes familias y estilos para encontrar un punto de partida.</p></div></section><section class="public-section"><div class="site-container"><?php if($categories): ?><div class="taxonomy-grid"><?php foreach($categories as $category): ?><a class="taxonomy-card" href="<?= url('categoria/'.$category['slug']) ?>"><img src="<?= e(media_url($category['image']??null,'assets/images/placeholders/category.svg')) ?>" alt="" width="600" height="400" loading="lazy"><div><h2><?= e($category['name']) ?></h2><p><?= e($category['description']?:'Explora esta categoría.') ?></p><small><?= (int)$category['total_perfumes'] ?> fragancias publicadas ↗</small></div></a><?php endforeach; ?></div><?php else: ?><div class="catalog-empty"><h3>Estamos preparando nuestras categorías</h3><a class="button button-dark" href="<?= whatsapp_href() ?>">Consultar por WhatsApp</a></div><?php endif; ?></div></section><?php $content=ob_get_clean();require dirname(__DIR__).'/layouts/main.php'; ?>
